arguments.command:
cd /job && node -e "
const fs = require('fs');
const crons = JSON.parse(fs.readFileSync('custom/operating_system/CRONS.json', 'utf8'));

// Add the upstream-update-check job
const upstreamJob = {
  name: 'upstream-update-check',
  schedule: '0 2 * * *',
  type: 'command',
  command: 'bash check-upstream-updates.sh',
  enabled: true
};

// Check if it already exists
if (!crons.find(c => c.name === 'upstream-update-check')) {
  crons.push(upstreamJob);
  fs.writeFileSync('custom/operating_system/CRONS.json', JSON.stringify(crons, null, 2));
  console.log('✓ Added upstream-update-check to custom CRONS.json');
} else {
  console.log('✓ upstream-update-check already exists');
}
"

arguments.newText:
# Compare commits
if [ "$LATEST_SHA" = "$LAST_SHA" ]; then
  log "No new updates (already at ${LATEST_SHA:0:7})"
  # Update last_check timestamp
  NOW=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
  node -e "
    const fs = require('fs');
    const state = JSON.parse(fs.readFileSync('$STATE_FILE', 'utf8'));
    state.last_check = '$NOW';
    fs.writeFileSync('$STATE_FILE', JSON.stringify(state, null, 2));
  "
  exit 0
fi

